function convertCustomTagsToDiv() {
  // Get all elements in the document
  const allElements = document.querySelectorAll('*');

  // Array to store elements that need to be replaced
  const elementsToReplace = [];

  // Find all custom tags ending with a dash
  allElements.forEach(element => {
    const tagName = element.tagName.toLowerCase();

    // Check if it's a custom tag ending with a dash
    if (tagName.endsWith('-') && tagName.includes('-')) {
      elementsToReplace.push(element);
    }
  });

  // Replace each custom tag with a div
  elementsToReplace.forEach(element => {
    const tagName = element.tagName.toLowerCase();

    // Create new div element
    const newDiv = document.createElement('div');

    // Add the class name (without the trailing dash)
    newDiv.className = tagName.slice(0, -1);

    // Copy all attributes except the tag name itself
    Array.from(element.attributes).forEach(attr => {
      newDiv.setAttribute(attr.name, attr.value);
    });

    // Move all child nodes to the new div
    while (element.firstChild) {
      newDiv.appendChild(element.firstChild);
    }

    // Replace the original element with the new div
    element.parentNode.replaceChild(newDiv, element);
  });

  console.log(`Converted ${elementsToReplace.length} custom tags to div elements`);
}

// Auto-invoke when DOM is loaded
document.addEventListener('DOMContentLoaded', function() {
  convertCustomTagsToDiv();
});

